def build():
    target=ROOT/'benchmark/advanced'
    if (target/'manifest.json').exists():raise ValueError('Benchmark already frozen')
    if not (DATA/'index.json').exists() or not (DATA/'vectors.json').exists():raise ValueError('Index full document first')
    cases={}
    for split,source,absences in [('dev',DEV,ABSENCE_DEV),('test',TEST,ABSENCE_TEST)]:
        rows=[]
        for number,(group,fact,question,answer,evidence) in enumerate(source,1):
            gold=[{'source_id':'arxiv-2303.08774v6','page':page,'region':region,'bbox':box,'description':description,
                   'page_image_sha256':sha(DATA/f'pages/page-{page:03}.jpg')} for page,region,box,description in evidence]
            rows.append({'id':f'adv-{split}-{number:02}','split':split,'group':group,'fact_key':fact,'question':question,
                'answerable':True,'expected_answer':answer,'gold':gold,
                'verification':'Codex AI read original rendered PDF page(s); not independent human confirmation.'})
        for number,(fact,question,reason,pages,terms) in enumerate(absences,1):
            rows.append({'id':f'adv-{split}-u{number:02}','split':split,'group':'unanswerable','fact_key':fact,'question':question,
                'answerable':False,'expected_answer':'Từ chối hoặc nêu rõ không đủ bằng chứng, không thêm phỏng đoán.','gold':[],
                'absence_reason':reason,'absence_check':{'pages_reviewed':pages,'search_terms':terms,
                    'method':'Full 100-page text/visual-index search plus source-page scope/figure inspection. No absence conclusion from top-k alone.'},
                'verification':'Codex AI corpus/scope review; not independent human confirmation.'})
        write(target/f'{split}.json',rows)
        write(target/'inputs'/f'{split}.json',[{'id':r['id'],'question':r['question']} for r in rows])
        cases[split]=len(rows)
    assets=[PDF,DATA/'index.json',DATA/'vectors.json',DATA/'manifest.json']
    assets+=list((DATA/'pages').glob('*.jpg'))
    assets+=[target/f'{s}.json' for s in ['dev','test']]+[target/'inputs'/f'{s}.json' for s in ['dev','test']]
    write(target/'manifest.json',{'version':'advanced-v1','created_at':now(),'counts':cases,
        'split_policy':'Distinct fact targets; shared source pages allowed. No question is merely a rephrasing of another split question.',
        'evidence_policy':'All listed gold regions/pages required; equivalent valid evidence accepted only with explicit source-review reason.',
        'selection_criteria':read(ROOT/'configs/advanced/experiments.json')['selection_criteria'],
        'source_review':'AI reviewed all gold page images and cited regions before any agent dev/test execution; human independence not claimed.',
        'sha256':{str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in assets}})
    print('Frozen benchmark:',cases)


if __name__=='__main__':build()
